"""Unit tests for the api/ layer — no Neo4j needed.

Tests business logic, validation, parameter passing, and return types
by mocking GraphConnection.execute_query.
"""

from types import SimpleNamespace
from unittest.mock import MagicMock, patch

import pytest

from multiomics_explorer.api import functions as api
from multiomics_explorer.kg import constants as _kg_constants


# ---------------------------------------------------------------------------
# Resolver-aware mocks (metabolite-identity surface §A). The 7 metabolite-ID
# tools now issue ONE `build_resolve_metabolite_curies` round-trip
# (`UNWIND $curies`) whenever metabolite ids are passed — even canonical ones.
# These helpers answer that query from an identity stub (each canonical-looking
# CURIE resolves to itself) so a test's fixed-order response list only serves
# the other queries. They work before the resolver exists (no such query →
# the list lines up exactly as before) and after.
# ---------------------------------------------------------------------------

_RESOLVER_MARK = "UNWIND $curies"
# `build_metabolite_stereo_relatives` (metabolite stereo-form hint) — the
# genes_by_metabolite hint query; answered `[]` (no relatives) by
# `_resolver_aware` and skipped by `_non_resolver_calls` so fixed-order
# response lists stay aligned. Inert before the builder exists.
_STEREO_RELATIVES_MARK = "AS relative_id"
# GO transport surface: the default-on GO detail arm. Answered `[]` (no GO
# rows) by `_resolver_aware` and skipped by `_non_resolver_calls`, exactly
# like the resolver / stereo queries, so the pre-existing fixed-order
# response lists (summary, metabolism arm, transport arm, probes) stay
# aligned and each test keeps asserting what it asserted before.
_GO_ARM_MARK = "'go_transport' AS evidence_source"
# TCDB cleanup surface: the always-on family-substrates hint query
# (`build_{genes_by_metabolite,metabolites_by_gene}_tcdb_family_hint`).
# Answered `[]` (nothing the opt-in walk would add — the api defaults the
# envelope to zeros / []) by `_resolver_aware` and skipped by
# `_non_resolver_calls`, like the marks above, so fixed-order response lists
# stay aligned. Inert before the builder exists.
_TCDB_FAMILY_HINT_MARK = "AS tcdb_family_substrates_skipped"
# Family-walk DETAIL query (`'family' AS tcdb_route`); the summary query, which
# always carries `AS total_matching`, may share the literal when the walk is on.
_TCDB_FAMILY_WALK_MARK = "'family' AS tcdb_route"
_RESOLVER_IDENTITY_PREFIXES = (
    "kegg.compound", "chebi", "mnx", "hmdb", "inchikey",
)


def _identity_resolver_rows(curies):
    def _canon(c):
        if ":" in c and c.split(":", 1)[0] in _RESOLVER_IDENTITY_PREFIXES:
            return [c]
        return []
    return [{"curie": c, "canonical": _canon(c), "recurated_to": [], "roles": []}
            for c in curies]


def _resolver_aware(responses):
    """`side_effect` replacement: resolver queries → identity stub; every
    other query consumes `responses` in order (same semantics as a
    MagicMock side_effect list, including raising exception items and
    StopIteration when exhausted)."""
    queue = list(responses)

    def _exec(cypher, *args, **params):
        if _RESOLVER_MARK in cypher:
            return _identity_resolver_rows(params.get("curies", []))
        if _GO_ARM_MARK in cypher:
            return []
        if _TCDB_FAMILY_HINT_MARK in cypher:
            return []
        if _STEREO_RELATIVES_MARK in cypher:
            # metabolite stereo-form hint: no stereo relatives in these
            # fixtures (also skips the relative-summary query).
            return []
        if not queue:
            raise StopIteration
        item = queue.pop(0)
        if isinstance(item, BaseException) or (
                isinstance(item, type) and issubclass(item, BaseException)):
            raise item
        return item

    return _exec


def _non_resolver_calls(conn):
    """`conn.execute_query.call_args_list` minus resolver round-trips."""
    out = []
    for c in conn.execute_query.call_args_list:
        cypher = c.args[0] if c.args else c.kwargs.get("cypher", "")
        if (_RESOLVER_MARK not in cypher and _STEREO_RELATIVES_MARK not in cypher
                and _GO_ARM_MARK not in cypher
                and _TCDB_FAMILY_HINT_MARK not in cypher):
            out.append(c)
    return out


# ---------------------------------------------------------------------------
# Top-level package re-exports
# ---------------------------------------------------------------------------
class TestTopLevelImports:
    def test_all_api_functions_importable_from_package(self):
        """from multiomics_explorer import <fn> works for every api function."""
        from multiomics_explorer import (
            gene_homologs,
            genes_by_function,
            list_clustering_analyses,
            resolve_gene,
            gene_clusters_by_gene,
            genes_in_cluster,
        )
        # Each should be the same object as in api.functions
        assert resolve_gene is api.resolve_gene
        assert gene_homologs is api.gene_homologs
        assert genes_by_function is api.genes_by_function
        assert list_clustering_analyses is api.list_clustering_analyses
        assert gene_clusters_by_gene is api.gene_clusters_by_gene
        assert genes_in_cluster is api.genes_in_cluster

    def test_query_expression_removed(self):
        """query_expression is no longer exported (schema migration B1)."""
        import multiomics_explorer
        assert not hasattr(multiomics_explorer, "query_expression")


@pytest.fixture()
def mock_conn():
    """A MagicMock GraphConnection."""
    return MagicMock()


@pytest.fixture(autouse=True)
def _reset_vocab_cache():
    """`_read_vocab_values` caches per (applies_to, prop) at module scope
    (real-KG perf optimisation) — without a reset, whichever test in this
    file happens to run first for a given pair silently seeds the cache
    for every later test, making mocked `execute_query.side_effect` call
    counts order-dependent. Reset before and after every test so each test
    sees a cold cache regardless of run order (llm-review 2b.3)."""
    api._reset_vocab_cache()
    yield
    api._reset_vocab_cache()


